01464     {
01465         $connected = @fsockopen('www.google.com', 80);
01466         if ($connected) {
01467             fclose($connected);
01468 
01469             return true; // Internet connection is active
01470         } else {
01471             return false; // Internet connection is not active
01472         }
01473     }



